<script module lang="ts">
    import { index } from '@/routes/notifications'; export const layout = { breadcrumbs: [{ title: 'Notifikasi', href: index() }] };
</script>
<script lang="ts">
    import { Link, page } from '@inertiajs/svelte'; import AppHead from '@/components/AppHead.svelte'; import PageHeader from '@/components/PageHeader.svelte'; import { Badge } from '@/components/ui/badge'; import { toUrl } from '@/lib/utils'; import { formatDate } from '@/lib/format-date'; import NotificationController from '@/actions/App/Http/Controllers/NotificationController'; import { index as notificationsIndex } from '@/routes/notifications';
    type Item = { id: string; title: string; message: string; url: string; read_at: string | null; created_at: string | null }; let { notifications, unread, unreadCount }: { notifications: Item[]; unread: boolean; unreadCount: number } = $props(); const workspaceTimezone = $derived(page.props.workspaceContext?.active?.timezone);
</script>
<AppHead title="Notifikasi" />
<div class="mx-auto flex w-full max-w-3xl flex-col gap-5 px-4 py-5 sm:px-6 lg:px-8">
    <PageHeader title="Notifikasi" description={unreadCount > 0 ? `${unreadCount} notifikasi belum dibaca.` : 'Semua notifikasi sudah dibaca.'}>
        {#snippet actions()}
            {#if unreadCount > 0}<Link href={toUrl(NotificationController.readAll())} method="post" as="button" class="inline-flex min-h-8 items-center rounded-md border px-2.5 text-xs hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring">Tandai semua dibaca</Link>{/if}
        {/snippet}
    </PageHeader>
    <nav class="flex gap-2" aria-label="Filter notifikasi"><Link href={toUrl(notificationsIndex())} aria-current={!unread ? 'page' : undefined} class="rounded-md border px-3 py-2 text-sm hover:bg-muted { !unread ? 'bg-muted font-medium' : 'text-muted-foreground' }">Semua</Link><Link href={toUrl(notificationsIndex({ query: { unread: 1 } }))} aria-current={unread ? 'page' : undefined} class="rounded-md border px-3 py-2 text-sm hover:bg-muted { unread ? 'bg-muted font-medium' : 'text-muted-foreground' }">Belum dibaca{#if unreadCount > 0}<Badge variant="secondary" class="ml-2">{unreadCount}</Badge>{/if}</Link></nav>{#if notifications.length === 0}<div class="rounded-lg border border-dashed px-6 py-12 text-center text-sm text-muted-foreground">{unread ? 'Tidak ada notifikasi belum dibaca.' : 'Belum ada notifikasi.'}</div>{:else}<div class="divide-y rounded-lg border bg-card">{#each notifications as notification (notification.id)}<div class="flex items-start justify-between gap-4 px-4 py-4 {notification.read_at ? '' : 'bg-muted/30'}"><Link href={notification.url} class="min-w-0 flex-1"><div class="flex items-center gap-2"><h2 class="text-sm font-semibold">{notification.title}</h2>{#if !notification.read_at}<Badge variant="secondary">Baru</Badge>{/if}</div><p class="mt-1 text-sm text-muted-foreground">{notification.message}</p><p class="mt-2 text-xs text-muted-foreground">{formatDate(notification.created_at, workspaceTimezone)}</p></Link>{#if !notification.read_at}<Link href={toUrl(NotificationController.read({ notification: notification.id }))} method="post" as="button" class="min-h-10 px-2 text-xs text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring">Tandai dibaca</Link>{/if}</div>{/each}</div>{/if}
